/**
 * Calendar arithmetic for subscription periods and mid-period proration. Pure: no I/O, so the renewal job and the billing service agree by construction.
 */
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

/** Months covered by one period of the given interval. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Moves a timestamp forward by whole calendar months in UTC, keeping the time
 * of day. When the target month has no such day the result is that month's
 * last day, so 31 January + 1 month is 28 February.
 */
export function addMonths(stamp: IsoTimestamp, months: number): IsoTimestamp {
  const from = new Date(stamp);
  const day = from.getUTCDate();

  const target = new Date(
    Date.UTC(
      from.getUTCFullYear(),
      from.getUTCMonth() + months,
      1,
      from.getUTCHours(),
      from.getUTCMinutes(),
      from.getUTCSeconds(),
      from.getUTCMilliseconds(),
    ),
  );

  const lastDay = new Date(
    Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0),
  ).getUTCDate();
  target.setUTCDate(Math.min(day, lastDay));

  return toIsoTimestamp(target);
}

/**
 * The part of a full-period charge that applies from `at` to the period end.
 * Days left are whole or started days (14 days 22 hours counts as 15), the
 * days in the period are whole days rounded and at least one, and the result
 * is rounded down to whole cents. Nothing is owed once the period has ended.
 */
export function prorateCents(
  fullCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  at: Date,
): number {
  const remainingMs = Date.parse(periodEnd) - at.getTime();
  if (remainingMs <= 0) return 0;

  const daysInPeriod = Math.max(
    1,
    Math.round((Date.parse(periodEnd) - Date.parse(periodStart)) / DAY_MS),
  );
  const daysLeft = Math.min(Math.ceil(remainingMs / DAY_MS), daysInPeriod);

  return Math.floor((fullCents * daysLeft) / daysInPeriod);
}

