import type {
  BillingInterval,
  PlanId,
  Subscription,
  SubscriptionStatus,
} from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

/** Columns a billing flow may move; anything not listed is left as it is. */
export type SubscriptionPatch = Partial<
  Pick<
    Subscription,
    | "plan"
    | "interval"
    | "status"
    | "seats"
    | "currentPeriodStart"
    | "currentPeriodEnd"
    | "cancelAt"
  >
>;
