'''/**
 * Applies a partial update and returns the row. The period, status and cancel
 * date move only when the caller names them.
 */
export async function patchSubscription(
  orgId: OrgId,
  patch: SubscriptionPatch,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * One page of subscriptions belonging to live workspaces, keyset-paged on the
 * subscription id so the renewal sweep never holds every row at once.
 */
export async function listLiveSubscriptions(
  afterId: string | null,
  limit: number,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        isNull(organizations.archivedAt),
        afterId === null ? undefined : gt(subscriptions.id, afterId),
      ),
    )
    .orderBy(asc(subscriptions.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

