'''/** A charge to invoice for one period; `issueInvoice` drops it when zero. */
type PeriodCharge = {
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
};

/**
 * Stores an invoice for a charge and announces it. A zero charge produces no
 * invoice at all, so callers can pass the arithmetic result straight through.
 */
export async function issueInvoice(
  orgId: OrgId,
  actorId: UserId | null,
  charge: PeriodCharge,
  at: Date,
): Promise<Invoice | null> {
  if (charge.amountCents <= 0) return null;

  const invoice = await invoiceRepo.insertInvoice(orgId, charge);

  await emit("billing.invoice_issued", {
    orgId,
    actorId,
    occurredAt: toIsoTimestamp(at),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

/** Price of `seats` seats for `months` months on `plan`, in cents. */
function fullChargeCents(
  plan: PlanId,
  seats: number,
  months: number,
): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * months;
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 *
 * Charging: a trial moves to the chosen plan without a charge and keeps its
 * period. Leaving the free plan starts a fresh, fully invoiced period. Between
 * two paid plans on an active subscription, an upgrade is charged for the
 * price difference over the rest of the current period; a downgrade is not.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = subscription.plan;
''')

