  let charge: PeriodCharge | null = null;

  if (subscription.status === "trialing") {
    charge = null;
  } else if (currentPlan === "free" && input.plan !== "free") {
    const periodStart = stamp;
    const periodEnd = addMonths(stamp, months);

    patch.currentPeriodStart = periodStart;
    patch.currentPeriodEnd = periodEnd;
    charge = {
      amountCents: fullChargeCents(input.plan, subscription.seats, months),
      periodStart,
      periodEnd,
    };
  } else if (
    currentPlan !== "free" &&
    input.plan !== "free" &&
    subscription.status === "active"
  ) {
    const difference =
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
      getPlanLimits(currentPlan).priceCentsPerSeatMonthly;

    if (difference > 0) {
      const subscriptionMonths = monthsInInterval(subscription.interval);
      charge = {
        amountCents: prorateCents(
          difference * subscription.seats * subscriptionMonths,
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
          now,
        ),
        periodStart: subscription.currentPeriodStart,
        periodEnd: subscription.currentPeriodEnd,
      };
    }
  }

  const updated = await subscriptionRepo.patchSubscription(input.orgId, patch);

  if (charge !== null) {
    await issueInvoice(input.orgId, actor.userId, charge, now);
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return updated;
}

/**
 * Seats added to an active paid subscription are charged for the rest of the
 * current period. Removing seats, and any change on the free plan or during a
 * trial, charges nothing.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const plan = subscription.plan;

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const now = new Date();
  const updated = await subscriptionRepo.updateSeatCount(input.orgId, input.seats);
  const added = input.seats - subscription.seats;

  if (plan !== "free" && subscription.status === "active" && added > 0) {
    const months = monthsInInterval(subscription.interval);
    await issueInvoice(
      input.orgId,
      actor.userId,
      {
        amountCents: prorateCents(
          fullChargeCents(plan, added, months),
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
          now,
        ),
        periodStart: subscription.currentPeriodStart,
        periodEnd: subscription.currentPeriodEnd,
      },
      now,
    );
  }

  return updated;
}
