 * Renews subscriptions whose period has ended, invoices each renewed paid period, and ends cancellations on their date.
 *
 * Must call (do not reimplement): addMonths, monthsInInterval, emit, getPlanLimits, issueInvoice, runJob
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addMonths, monthsInInterval } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

/** Subscriptions read per page; the sweep pages through every workspace. */
const PAGE_SIZE = 100;

/** Where a subscription lands when its cancellation takes effect. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * The hourly billing sweep. Each `active` subscription rolls forward one period
 * per elapsed interval, invoicing every renewed paid period; a `canceled` one
 * whose cancellation date has come moves to the free plan. Trials and past-due
 * subscriptions are left to their own flows.
 *
 * Replay-safe: a period only rolls forward once, so running the job again at
 * the same instant finds nothing due.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let afterId: string | null = null;

    for (;;) {
      const page = await subscriptionRepo.listLiveSubscriptions(
        afterId,
        PAGE_SIZE,
      );

      for (const subscription of page) {
        try {
          if (await settle(subscription, now)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      const last = page.at(-1);
      if (last === undefined || page.length < PAGE_SIZE) break;
      afterId = last.id;
    }
  });
}

/** Returns true when the subscription changed. */
async function settle(subscription: Subscription, now: Date): Promise<boolean> {
  if (subscription.status === "canceled") {
    return endCancellation(subscription, now);
  }
  if (subscription.status === "active") {
    return renewPeriods(subscription, now);
  }
  return false;
}

async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  const cancelAt = subscription.cancelAt;
  if (cancelAt === null || cancelAt > toIsoTimestamp(now)) return false;

  await subscriptionRepo.patchSubscription(subscription.orgId, {
    plan: FALLBACK_PLAN,
    interval: "monthly",
    status: "active",
    cancelAt: null,
    currentPeriodStart: cancelAt,
    currentPeriodEnd: addMonths(cancelAt, 1),
  });

  if (subscription.plan !== FALLBACK_PLAN) {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: cancelAt,
      from: subscription.plan,
      to: FALLBACK_PLAN,
    });
  }

  return true;
}

/**
 * Rolls the period forward until its end lies after `now`. Each new period is
 * invoiced first (paid plans only) and then stored, so an interrupted run
 * leaves the period unmoved and the next run resumes from it.
 */
async function renewPeriods(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  const stamp = toIsoTimestamp(now);
  const months = monthsInInterval(subscription.interval);
  const paid = subscription.plan !== FALLBACK_PLAN;
  const pricePerSeat = getPlanLimits(subscription.plan).priceCentsPerSeatMonthly;

  let periodEnd: IsoTimestamp = subscription.currentPeriodEnd;
  let renewed = false;

  while (periodEnd <= stamp) {
    const periodStart = periodEnd;
    const nextEnd = addMonths(periodStart, months);

    if (paid) {
      const alreadyInvoiced =
        (await invoiceRepo.findInvoiceByPeriodStart(
          subscription.orgId,
          periodStart,
        )) !== null;

      if (!alreadyInvoiced) {
        await issueInvoice(
          subscription.orgId,
          null,
          {
            amountCents: pricePerSeat * subscription.seats * months,
            periodStart,
            periodEnd: nextEnd,
          },
          now,
        );
      }
    }

    await subscriptionRepo.patchSubscription(subscription.orgId, {
      currentPeriodStart: periodStart,
      currentPeriodEnd: nextEnd,
    });

    periodEnd = nextEnd;
    renewed = true;
  }

  return renewed;
}
