/**
 * Period renewal, invoicing and cancellation end-dates for the billing sweep,
 * plus the calendar arithmetic it relies on.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { addMonths, prorateCents } from "@/lib/billing-period";
import { subscribe } from "@/lib/event-bus";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function stamp(value: string): IsoTimestamp {
  return value as IsoTimestamp;
}

describe("lib/billing-period", () => {
  it("clamps to the last day of a shorter month and carries the clamp forward", () => {
    expect(addMonths(stamp("2026-01-31T09:00:00.000Z"), 1)).toBe("2026-02-28T09:00:00.000Z");
    expect(addMonths(stamp("2026-02-28T09:00:00.000Z"), 1)).toBe("2026-03-28T09:00:00.000Z");
    expect(addMonths(stamp("2028-02-29T00:00:00.000Z"), 12)).toBe("2029-02-28T00:00:00.000Z");
  });

  it("counts days left as started days and rounds the charge down", () => {
    const start = stamp("2026-06-01T00:00:00.000Z");
    const end = stamp("2026-07-01T00:00:00.000Z"); // 30 days
    // 14 days and 22 hours left counts as 15 days.
    const at = new Date("2026-06-16T02:00:00.000Z");
    expect(prorateCents(3_000, start, end, at)).toBe(1_500);
    // Nothing is owed once the period end has been reached.
    expect(prorateCents(3_000, start, end, new Date("2026-07-01T00:00:00.000Z"))).toBe(0);
  });
});

describe("jobs/billing-renewal-job", () => {
  async function activeTenant(slug: string, plan: "growth" | "free"): Promise<Tenant> {
    const tenant = await createTenant(slug, plan);
    await subscriptionRepo.patchSubscription(tenant.org.id, {
      status: "active",
      seats: 2,
      currentPeriodStart: stamp("2026-01-31T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-02-28T00:00:00.000Z"),
    });
    return tenant;
  }

  it("renews every elapsed period and invoices each paid one", async () => {
    const tenant = await activeTenant("renew-paid", "growth");

    await runBillingRenewalJob(new Date("2026-04-15T12:00:00.000Z"));

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe("2026-03-28T00:00:00.000Z");
    expect(subscription?.currentPeriodEnd).toBe("2026-04-28T00:00:00.000Z");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(2);
    expect(invoices.map((invoice) => invoice.amountCents)).toEqual([3_800, 3_800]);
    expect(invoices[0]?.periodStart).toBe("2026-03-28T00:00:00.000Z");
  });

  it("does nothing when run again at the same instant", async () => {
    const tenant = await activeTenant("renew-replay", "growth");
    const at = new Date("2026-04-15T12:00:00.000Z");

    await runBillingRenewalJob(at);
    const second = await runBillingRenewalJob(at);

    expect(second.processed).toBe(0);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(2);
  });

  it("rolls free periods forward without invoices", async () => {
    const tenant = await activeTenant("renew-free", "free");

    await runBillingRenewalJob(new Date("2026-04-15T12:00:00.000Z"));

    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodEnd).toBe("2026-04-28T00:00:00.000Z");
  });

  it("leaves trialing subscriptions alone", async () => {
    const tenant = await createTenant("renew-trial", "growth");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);

    await runBillingRenewalJob(new Date("2099-01-01T00:00:00.000Z"));

    const after = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(after?.currentPeriodEnd).toBe(before?.currentPeriodEnd);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

  it("ends a cancellation on its date and announces it once", async () => {
    const tenant = await activeTenant("cancel-ends", "growth");
    await subscriptionRepo.cancelSubscription(
      tenant.org.id,
      stamp("2026-03-01T00:00:00.000Z"),
    );

    const seen: unknown[] = [];
    const off: Unsubscribe = subscribe("billing.plan_changed", (payload) => {
      seen.push(payload);
    });

    await runBillingRenewalJob(new Date("2026-03-02T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2026-03-02T00:00:00.000Z"));
    off();

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "free",
      status: "active",
      cancelAt: null,
      currentPeriodStart: "2026-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-04-01T00:00:00.000Z",
    });
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ orgId: tenant.org.id, from: "growth", to: "free" });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });
});
EOF
